// Drizzle schema for STONEMILES — dialect dispatcher (Phase 2a).
//
// This module is what server code imports as "./schema". It re-exports
// one of two generated dialect twins with identical export names:
//
//   schema-sqlite.ts — drizzle-orm/sqlite-core (Phase 1 standalone proof)
//   schema-pg.ts     — drizzle-orm/pg-core     (Phase 2a, generated by
//                      host/pg/transform-schema.ts from the SQLite twin)
//
// Selection: STONEMILES_DIALECT=postgres -> pg twin; anything else ->
// SQLite twin (the Phase 1 default; the SQLite path is unchanged).
// Types are pinned to the SQLite twin (the default path) so the action
// code typechecks exactly as it did in Phase 1; the host hands actions
// a ctx.db() built over the matching dialect twin at runtime (see
// host/ctx.ts getDb()).

import * as lite from "./schema-sqlite";
import * as pg from "./schema-pg";

const impl = (
  process.env.STONEMILES_DIALECT === "postgres" ? pg : lite
) as unknown as typeof lite;

